window.ACTIVE_PARALLELDOC_RAW = "{\n  \"$schema\": \"https://antigravity.local/schemas/cockpit-v1.json\",\n  \"metadata\": {\n    \"title\": \"Sample: Cloud Infrastructure SLA & Security Compliance Review\",\n    \"document_id\": \"DOC-2026-SEC-SLA-001\",\n    \"created_at\": \"2026-09-04T12:00:00Z\",\n    \"source_file\": \"cloud_sla_security_specification.docx\"\n  },\n  \"columns\": [\n    { \"key\": \"col1\", \"title\": \"Original Clause (EN)\", \"width_weight\": 30 },\n    { \"key\": \"col2\", \"title\": \"Target Translation (UA)\", \"width_weight\": 30 },\n    { \"key\": \"col3\", \"title\": \"Engineering & Risk Assessment (EN)\", \"width_weight\": 40 }\n  ],\n  \"items\": [\n    {\n      \"id\": \"1\",\n      \"col1\": \"1. High Availability and Uptime: The Contractor guarantees monthly service availability of at least 99.95%, excluding scheduled maintenance windows announced at least 48 hours in advance. Failure to meet this SLA incurs a 10% penalty credit per hour of downtime.\",\n      \"col2\": \"1. \u0412\u0438\u0441\u043e\u043a\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0456\u0441\u0442\u044c \u0442\u0430 \u0431\u0435\u0437\u0432\u0456\u0434\u043c\u043e\u0432\u043d\u0430 \u0440\u043e\u0431\u043e\u0442\u0430: \u0412\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c \u0433\u0430\u0440\u0430\u043d\u0442\u0443\u0454 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0456\u0441\u0442\u044c \u0441\u0435\u0440\u0432\u0456\u0441\u0443 \u043d\u0435 \u043c\u0435\u043d\u0448\u0435 99.95% \u043d\u0430 \u043c\u0456\u0441\u044f\u0446\u044c, \u0437\u0430 \u0432\u0438\u043d\u044f\u0442\u043a\u043e\u043c \u043f\u043b\u0430\u043d\u043e\u0432\u0438\u0445 \u0440\u0435\u0433\u043b\u0430\u043c\u0435\u043d\u0442\u043d\u0438\u0445 \u0440\u043e\u0431\u0456\u0442, \u0430\u043d\u043e\u043d\u0441\u043e\u0432\u0430\u043d\u0438\u0445 \u0449\u043e\u043d\u0430\u0439\u043c\u0435\u043d\u0448\u0435 \u0437\u0430 48 \u0433\u043e\u0434\u0438\u043d. \u041f\u043e\u0440\u0443\u0448\u0435\u043d\u043d\u044f SLA \u0442\u044f\u0433\u043d\u0435 \u0437\u0430 \u0441\u043e\u0431\u043e\u044e \u0448\u0442\u0440\u0430\u0444\u043d\u0438\u0439 \u043a\u0440\u0435\u0434\u0438\u0442 \u0443 \u0440\u043e\u0437\u043c\u0456\u0440\u0456 10% \u0437\u0430 \u043a\u043e\u0436\u043d\u0443 \u0433\u043e\u0434\u0438\u043d\u0443 \u043f\u0440\u043e\u0441\u0442\u043e\u044e.\",\n      \"col3\": \"\u2705 **Compliance & Architecture Feasibility:**\\n\\n- Multi-AZ architecture satisfies the target 99.95% SLA (historical uptime: 99.99%).\\n- Automated failover MTTR is under 45 seconds.\\n- **Risk:** Low. Automated health monitoring via CloudWatch/Prometheus required.\"\n    },\n    {\n      \"id\": \"2\",\n      \"col1\": \"2. Cryptographic Controls and Encryption: All customer data at rest must be encrypted using AES-256-GCM. All data in transit across public networks must enforce TLS 1.3 with forward secrecy. Deprecated ciphers (including RSA key exchange and CBC suites) are strictly prohibited.\",\n      \"col2\": \"2. \u041a\u0440\u0438\u043f\u0442\u043e\u0433\u0440\u0430\u0444\u0456\u0447\u043d\u0438\u0439 \u0437\u0430\u0445\u0438\u0441\u0442 \u0442\u0430 \u0448\u0438\u0444\u0440\u0443\u0432\u0430\u043d\u043d\u044f: \u0423\u0441\u0456 \u0434\u0430\u043d\u0456 \u043a\u043b\u0456\u0454\u043d\u0442\u0456\u0432 \u0443 \u0441\u0442\u0430\u043d\u0456 \u0441\u043f\u043e\u043a\u043e\u044e \u043f\u043e\u0432\u0438\u043d\u043d\u0456 \u0448\u0438\u0444\u0440\u0443\u0432\u0430\u0442\u0438\u0441\u044f \u0437\u0430 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043e\u043c AES-256-GCM. \u041f\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u0434\u0430\u043d\u0438\u0445 \u0447\u0435\u0440\u0435\u0437 \u043f\u0443\u0431\u043b\u0456\u0447\u043d\u0456 \u043c\u0435\u0440\u0435\u0436\u0456 \u0437\u043e\u0431\u043e\u0432'\u044f\u0437\u0430\u043d\u0430 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0432\u0430\u0442\u0438 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b TLS 1.3 \u0456\u0437 \u0433\u0430\u0440\u0430\u043d\u0442\u0456\u0454\u044e \u043f\u0440\u044f\u043c\u043e\u0457 \u0441\u0435\u043a\u0440\u0435\u0442\u043d\u043e\u0441\u0442\u0456 (PFS). \u0417\u0430\u0441\u0442\u0430\u0440\u0456\u043b\u0456 \u0448\u0438\u0444\u0440\u0438 (\u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0447\u0438 RSA key exchange \u0442\u0430 CBC) \u0441\u0443\u0432\u043e\u0440\u043e \u0437\u0430\u0431\u043e\u0440\u043e\u043d\u0435\u043d\u0456.\",\n      \"col3\": \"\ud83d\udd12 **Security Standards Alignment:**\\n\\n- Databases enforce hardware disk encryption with KMS key rotation every 90 days.\\n- Ingress controller forcibly rejects client sessions below TLS 1.3.\\n- Zero-plaintext storage policy is codified in the architecture specification.\"\n    },\n    {\n      \"id\": \"3\",\n      \"col1\": \"3. Incident Notification and Escalation Window: In the event of a suspected or confirmed security breach, the Contractor shall notify the Client's CISO within 24 hours of first detection and provide an initial RCA report within 72 hours.\",\n      \"col2\": \"3. \u0420\u0435\u0433\u043b\u0430\u043c\u0435\u043d\u0442 \u0441\u043f\u043e\u0432\u0456\u0449\u0435\u043d\u043d\u044f \u043f\u0440\u043e \u0456\u043d\u0446\u0438\u0434\u0435\u043d\u0442\u0438: \u0423 \u0440\u0430\u0437\u0456 \u043f\u0456\u0434\u043e\u0437\u0440\u0438 \u0430\u0431\u043e \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0432\u0438\u0442\u043e\u043a\u0443 \u0434\u0430\u043d\u0438\u0445 \u0412\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c \u0437\u043e\u0431\u043e\u0432'\u044f\u0437\u0430\u043d\u0438\u0439 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u0438\u0442\u0438 CISO \u0417\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0430 \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 24 \u0433\u043e\u0434\u0438\u043d \u0437 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u043f\u0435\u0440\u0448\u043e\u0433\u043e \u0432\u0438\u044f\u0432\u043b\u0435\u043d\u043d\u044f \u0442\u0430 \u043d\u0430\u0434\u0430\u0442\u0438 \u043f\u0435\u0440\u0432\u0438\u043d\u043d\u0438\u0439 \u0437\u0432\u0456\u0442 \u043f\u0440\u043e \u0430\u043d\u0430\u043b\u0456\u0437 \u043f\u0435\u0440\u0448\u043e\u043f\u0440\u0438\u0447\u0438\u043d (RCA) \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 72 \u0433\u043e\u0434\u0438\u043d.\",\n      \"col3\": \"\u26a1 **Operational Readiness:**\\n\\n- 24/7/365 SOC coverage with internal response objective (MTTA) <= 15 minutes.\\n- 24-hour escalation requirement is met with substantial buffer.\\n- Integrated with PagerDuty and automated incident playbooks.\"\n    },\n    {\n      \"id\": \"4\",\n      \"col1\": \"4. Intellectual Property and Licensing Rights: All custom automation scripts, infrastructure-as-code manifests, and integration connectors developed specifically under this SOW shall remain the exclusive intellectual property of the Client upon final milestone acceptance.\",\n      \"col2\": \"4. \u0406\u043d\u0442\u0435\u043b\u0435\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0430 \u0432\u043b\u0430\u0441\u043d\u0456\u0441\u0442\u044c \u0442\u0430 \u043b\u0456\u0446\u0435\u043d\u0437\u0456\u0439\u043d\u0456 \u043f\u0440\u0430\u0432\u0430: \u0423\u0441\u0456 \u0441\u043f\u0435\u0446\u0456\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0456 \u0441\u043a\u0440\u0438\u043f\u0442\u0438 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0437\u0430\u0446\u0456\u0457, \u043c\u0430\u043d\u0456\u0444\u0435\u0441\u0442\u0438 \u0456\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438 \u044f\u043a \u043a\u043e\u0434\u0443 (IaC) \u0442\u0430 \u0456\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0456\u0439\u043d\u0456 \u043c\u043e\u0434\u0443\u043b\u0456, \u0440\u043e\u0437\u0440\u043e\u0431\u043b\u0435\u043d\u0456 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u0446\u044c\u043e\u0433\u043e \u0422\u0417, \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u044f\u0442\u044c \u0443 \u0432\u0438\u043a\u043b\u044e\u0447\u043d\u0443 \u0432\u043b\u0430\u0441\u043d\u0456\u0441\u0442\u044c \u0417\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0430 \u043f\u0456\u0441\u043b\u044f \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u0439\u043c\u0430\u043d\u043d\u044f \u0435\u0442\u0430\u043f\u0443.\",\n      \"col3\": \"\ud83d\udcc4 **Licensing Review:**\\n\\n- Proprietary platform libraries are delivered under permissive MIT / Apache 2.0 terms.\\n- Client-specific code is isolated in a dedicated repository.\\n- Zero patent or licensing conflicts identified.\"\n    },\n    {\n      \"id\": \"5\",\n      \"col1\": \"5. Independent Audit and Verification: The Client reserves the right to conduct an annual third-party SOC 2 Type II or ISO/IEC 27001 compliance assessment. The Contractor shall facilitate log access and evidence inspection without undue delay.\",\n      \"col2\": \"5. \u041d\u0435\u0437\u0430\u043b\u0435\u0436\u043d\u0438\u0439 \u0430\u0443\u0434\u0438\u0442 \u0442\u0430 \u0432\u0435\u0440\u0438\u0444\u0456\u043a\u0430\u0446\u0456\u044f: \u0417\u0430\u043c\u043e\u0432\u043d\u0438\u043a \u0437\u0430\u043b\u0438\u0448\u0430\u0454 \u0437\u0430 \u0441\u043e\u0431\u043e\u044e \u043f\u0440\u0430\u0432\u043e \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442\u0438 \u0449\u043e\u0440\u0456\u0447\u043d\u0438\u0439 \u043d\u0435\u0437\u0430\u043b\u0435\u0436\u043d\u0438\u0439 \u0430\u0443\u0434\u0438\u0442 \u043d\u0430 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u043d\u0456\u0441\u0442\u044c \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0430\u043c SOC 2 Type II \u0430\u0431\u043e ISO/IEC 27001. \u0412\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c \u0437\u043e\u0431\u043e\u0432'\u044f\u0437\u0443\u0454\u0442\u044c\u0441\u044f \u0441\u0432\u043e\u0454\u0447\u0430\u0441\u043d\u043e \u043d\u0430\u0434\u0430\u0442\u0438 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0430\u043c \u0434\u043e\u0441\u0442\u0443\u043f \u0434\u043e \u0436\u0443\u0440\u043d\u0430\u043b\u0456\u0432 \u0442\u0430 \u0434\u043e\u043a\u0430\u0437\u043e\u0432\u043e\u0457 \u0431\u0430\u0437\u0438.\",\n      \"col3\": \"\ud83d\udee1\ufe0f **Audit Preparedness:**\\n\\n- Annual SOC 2 Type II assessment is completed and maintained by an accredited independent auditor.\\n- Immutable Audit Logs are stored in tamper-proof S3 WORM storage with deletion locks.\\n- Routine compliance review proceeds without operational friction.\"\n    }\n  ]\n}\n";
